import * as THREE from 'three/webgpu';
import * as TSL from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture
  const texture = ctx.textureLoader.load(config.assetUrls.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry and material with TSL
  const geometry = new THREE.PlaneGeometry(1, 1);
  const colorNode = TSL.texture(texture);
  const material = new THREE.MeshBasicNodeMaterial({ colorNode });

  // Create mesh with scene placement
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...config.scenePosition);
  mesh.rotation.set(...config.sceneRotation);

  if (config.sceneScale) {
    if (Array.isArray(config.sceneScale)) {
      mesh.scale.set(...config.sceneScale);
    } else {
      mesh.scale.setScalar(config.sceneScale);
    }
  }

  group.add(mesh);

  // Render text via font atlas
  const textContent = config.textContent?.[0];
  if (textContent?.text) {
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: textContent.text,
      fontSize: 0.34,
      fontWeight: textContent.weight || 400,
      fontFamily: 'Lora',
      color: config.colors.paper,
      align: 'center'
    });
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Cleanup resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
